CREATE TABLE avi_document(id INTEGER PRIMARY KEY CHECK(id=1),schema_identity TEXT NOT NULL,idx1_present INTEGER NOT NULL CHECK(idx1_present IN(0,1)));
CREATE TABLE avi_main_header(id INTEGER PRIMARY KEY REFERENCES avi_document(id) CHECK(id=1),micro_sec_per_frame INTEGER NOT NULL CHECK(micro_sec_per_frame BETWEEN 0 AND 4294967295),max_bytes_per_sec INTEGER NOT NULL CHECK(max_bytes_per_sec BETWEEN 0 AND 4294967295),padding_granularity INTEGER NOT NULL CHECK(padding_granularity BETWEEN 0 AND 4294967295),flags INTEGER NOT NULL CHECK(flags BETWEEN 0 AND 4294967295),total_frames INTEGER NOT NULL CHECK(total_frames BETWEEN 0 AND 4294967295),initial_frames INTEGER NOT NULL CHECK(initial_frames BETWEEN 0 AND 4294967295),streams INTEGER NOT NULL CHECK(streams BETWEEN 0 AND 4294967295),suggested_buffer_size INTEGER NOT NULL CHECK(suggested_buffer_size BETWEEN 0 AND 4294967295),width INTEGER NOT NULL CHECK(width BETWEEN 0 AND 4294967295),height INTEGER NOT NULL CHECK(height BETWEEN 0 AND 4294967295));
CREATE TABLE avi_main_reserved(id INTEGER PRIMARY KEY,header_id INTEGER NOT NULL REFERENCES avi_main_header(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),value INTEGER NOT NULL CHECK(value BETWEEN 0 AND 4294967295));
CREATE TABLE avi_stream(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES avi_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),format_kind TEXT NOT NULL CHECK(format_kind IN('bitmapInfo','waveFormat','raw')));
CREATE TABLE avi_stream_header(id INTEGER PRIMARY KEY REFERENCES avi_stream(id),fcc_type TEXT NOT NULL,fcc_handler TEXT NOT NULL,flags INTEGER NOT NULL CHECK(flags BETWEEN 0 AND 4294967295),priority INTEGER NOT NULL CHECK(priority BETWEEN 0 AND 65535),language INTEGER NOT NULL CHECK(language BETWEEN 0 AND 65535),initial_frames INTEGER NOT NULL CHECK(initial_frames BETWEEN 0 AND 4294967295),scale INTEGER NOT NULL CHECK(scale BETWEEN 0 AND 4294967295),rate INTEGER NOT NULL CHECK(rate BETWEEN 0 AND 4294967295),start INTEGER NOT NULL CHECK(start BETWEEN 0 AND 4294967295),length INTEGER NOT NULL CHECK(length BETWEEN 0 AND 4294967295),suggested_buffer_size INTEGER NOT NULL CHECK(suggested_buffer_size BETWEEN 0 AND 4294967295),quality INTEGER NOT NULL CHECK(quality BETWEEN -2147483648 AND 2147483647),sample_size INTEGER NOT NULL CHECK(sample_size BETWEEN 0 AND 4294967295),rc_frame_left INTEGER NOT NULL CHECK(rc_frame_left BETWEEN -2147483648 AND 2147483647),rc_frame_top INTEGER NOT NULL CHECK(rc_frame_top BETWEEN -2147483648 AND 2147483647),rc_frame_right INTEGER NOT NULL CHECK(rc_frame_right BETWEEN -2147483648 AND 2147483647),rc_frame_bottom INTEGER NOT NULL CHECK(rc_frame_bottom BETWEEN -2147483648 AND 2147483647),rc_frame_width INTEGER NOT NULL CHECK(rc_frame_width BETWEEN 0 AND 255),strh_extra BLOB NOT NULL);
CREATE TABLE avi_bitmap_info(id INTEGER PRIMARY KEY REFERENCES avi_stream(id),size INTEGER NOT NULL CHECK(size BETWEEN 0 AND 4294967295),width INTEGER NOT NULL CHECK(width BETWEEN -2147483648 AND 2147483647),height INTEGER NOT NULL CHECK(height BETWEEN -2147483648 AND 2147483647),planes INTEGER NOT NULL CHECK(planes BETWEEN 0 AND 65535),bit_count INTEGER NOT NULL CHECK(bit_count BETWEEN 0 AND 65535),compression TEXT NOT NULL,size_image INTEGER NOT NULL CHECK(size_image BETWEEN 0 AND 4294967295),x_pels_per_meter INTEGER NOT NULL CHECK(x_pels_per_meter BETWEEN -2147483648 AND 2147483647),y_pels_per_meter INTEGER NOT NULL CHECK(y_pels_per_meter BETWEEN -2147483648 AND 2147483647),colors_used INTEGER NOT NULL CHECK(colors_used BETWEEN 0 AND 4294967295),colors_important INTEGER NOT NULL CHECK(colors_important BETWEEN 0 AND 4294967295));
CREATE TABLE avi_wave_format(id INTEGER PRIMARY KEY REFERENCES avi_stream(id),format_tag INTEGER NOT NULL CHECK(format_tag BETWEEN 0 AND 65535),channels INTEGER NOT NULL CHECK(channels BETWEEN 0 AND 65535),samples_per_sec INTEGER NOT NULL CHECK(samples_per_sec BETWEEN 0 AND 4294967295),avg_bytes_per_sec INTEGER NOT NULL CHECK(avg_bytes_per_sec BETWEEN 0 AND 4294967295),block_align INTEGER NOT NULL CHECK(block_align BETWEEN 0 AND 65535),bits_per_sample INTEGER NOT NULL CHECK(bits_per_sample BETWEEN 0 AND 65535),extra BLOB NOT NULL);
CREATE TABLE avi_raw_format(id INTEGER PRIMARY KEY REFERENCES avi_stream(id),data BLOB NOT NULL);
CREATE TABLE avi_stream_chunk(id INTEGER PRIMARY KEY,stream_id INTEGER NOT NULL REFERENCES avi_stream(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),fourcc TEXT NOT NULL,data BLOB NOT NULL,keyframe INTEGER NOT NULL CHECK(keyframe IN(0,1)));
CREATE TABLE avi_stream_extra(id INTEGER PRIMARY KEY,stream_id INTEGER NOT NULL REFERENCES avi_stream(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),fourcc TEXT NOT NULL,data BLOB NOT NULL);
CREATE TABLE avi_unknown_chunk(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES avi_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),fourcc TEXT NOT NULL,data BLOB NOT NULL);
CREATE TABLE avi_hdrl_extra(id INTEGER PRIMARY KEY,document_id INTEGER NOT NULL REFERENCES avi_document(id),ordinal INTEGER NOT NULL CHECK(ordinal>=0),fourcc TEXT NOT NULL,data BLOB NOT NULL);
